import { log } from "../log.js";
import { getCliName } from "../utils/cli_name.js";
import { AUTH_CHILD } from "./child.js";
import { assertNamedAgentTooling, childArgv, chooseYesAgentTooling, collectYesAgents, initYesSupportedAgents, noDetectedAgentsMessage, planAgentSteps, planToolingSteps, planYesAgentSteps, resolveInitAgentSetup } from "./plan.js";
import { canPickAgentsInteractively } from "../utils/agent_picker.js";
import { detectAgent } from "./detect_host.js";
import { pickAgentSetupInteractively } from "./wizard.js";
import { detectProjectAgents } from "add-mcp";
//#region src/init/tooling.ts
const defaultProjectAgents = (cwd) => detectProjectAgents(cwd);
const runInitSteps = async (steps, options) => {
	for (const step of steps) {
		log.info("Running `%s %s`", getCliName(), step.join(" "));
		const argv = childArgv(step, options.forward);
		const command = step[0];
		if (!await options.run(argv, options.cwd, command !== void 0 && AUTH_CHILD.has(command) ? options.authEnv : void 0)) throw new Error(`\`${getCliName()} ${step.join(" ")}\` failed.`);
	}
};
const yesAgentsFromOptions = async (options) => collectYesAgents({
	detected: () => (options.detectProjectAgents ?? defaultProjectAgents)(options.cwd),
	detectAgent: options.detectAgent ?? detectAgent
});
const yesMiss = () => new Error(noDetectedAgentsMessage({
	scope: "project",
	supported: initYesSupportedAgents(),
	fix: "run-without-yes",
	nameAgent: true
}));
const runAgentTooling = async (options) => {
	const yes = options.yes;
	const named = options.agents ?? [];
	if (named.length > 0) {
		assertNamedAgentTooling(named, options.command ?? "init");
		const tooling = chooseYesAgentTooling(named);
		await runInitSteps(planToolingSteps(tooling, {
			yes,
			named: true
		}), options);
		return tooling.setup;
	}
	if (options.agentSetup !== void 0) {
		await runInitSteps(planAgentSteps({
			yes,
			agentSetup: options.agentSetup
		}), options);
		return options.agentSetup;
	}
	if (yes) {
		if (options.hasProjectPlugins !== void 0) {
			const agentSetup = await options.hasProjectPlugins(options.cwd) ? "plugin" : "skills-mcp";
			await runInitSteps(planAgentSteps({
				yes: true,
				agentSetup
			}), options);
			return agentSetup;
		}
		const agents = await yesAgentsFromOptions(options);
		const tooling = chooseYesAgentTooling(agents);
		if (tooling.setup === "skip") throw yesMiss();
		await runInitSteps(planYesAgentSteps(tooling), options);
		return tooling.setup;
	}
	const interactive = options.pickAgentSetup !== void 0 || canPickAgentsInteractively();
	const agentSetup = await resolveInitAgentSetup({
		interactive,
		pick: options.pickAgentSetup ?? pickAgentSetupInteractively
	});
	await runInitSteps(planAgentSteps({
		yes,
		agentSetup
	}), options);
	return agentSetup;
};
const runScaffoldFollowUp = async (options) => {
	if (!options.skipAgentSetup) await runAgentTooling(options);
	if (options.shouldLink) await runInitSteps([options.linkYes ? ["link", "--yes"] : ["link"]], options);
};
//#endregion
export { runAgentTooling, runInitSteps, runScaffoldFollowUp };
